    affiliateLinks: [{"label": "エリクシール レチノパワー（資生堂）（楽天）", "label_en": "Elixir Retino Power (Shiseido) (Rakuten)", "url": "https://hb.afl.rakuten.co.jp/hgc/g00t3lin.kll752db.g00t3lin.kll763d7/?pc=https%3A%2F%2Fitem.rakuten.co.jp%2Fyayoi-cosme%2F21468-m%2F&m=http%3A%2F%2Fm.rakuten.co.jp%2Fyayoi-cosme%2Fi%2F10014729%2F&rafcid=wsc_i_is_c18bf7b5-1871-492a-a3f5-afa07ce3dd0a"}, {"label": "キュレル 潤浸保湿 フェイスクリーム（花王）（楽天）", "label_en": "Curel Intensive Moisture Face Cream (Kao) (Rakuten)", "url": "https://hb.afl.rakuten.co.jp/hgc/g00qvyfn.kll758cb.g00qvyfn.kll76afe/?pc=https%3A%2F%2Fitem.rakuten.co.jp%2Fsundrug%2F4901301236210%2F&m=http%3A%2F%2Fm.rakuten.co.jp%2Fsundrug%2Fi%2F10025267%2F&rafcid=wsc_i_is_c18bf7b5-1871-492a-a3f5-afa07ce3dd0a"}, {"label": "オルビス 薬用クリアフルシリーズ（大人ニキビ用スキンケア）", "label_en": "ORBIS Medicated Clearful Series (for adult acne care)", "url": "https://px.a8.net/svt/ejp?a8mat=4B5OO1+9QOC36+1USQ+BXYEA"}],
