    affiliateLinks: [{"label": "「改訂版 本当の自由を手に入れる お金の大学」（両＠リベ大学長）", "label_en": "Okane no Daigaku (Money University), revised ed. (Japanese)", "url": "https://hb.afl.rakuten.co.jp/hgc/g00q072n.kll75f32.g00q072n.kll76c1e/?pc=https%3A%2F%2Fitem.rakuten.co.jp%2Fbook%2F18041936%2F&m=http%3A%2F%2Fm.rakuten.co.jp%2Fbook%2Fi%2F21432338%2F&rafcid=wsc_i_is_c18bf7b5-1871-492a-a3f5-afa07ce3dd0a"}, {"label": "「サイコロジー・オブ・マネー 一生お金に困らない「富」のマインドセット」（モーガン・ハウセル）", "label_en": "The Psychology of Money — Morgan Housel (Japanese edition)", "url": "https://hb.afl.rakuten.co.jp/hgc/g00q072n.kll75f32.g00q072n.kll76c1e/?pc=https%3A%2F%2Fitem.rakuten.co.jp%2Fbook%2F16915229%2F&m=http%3A%2F%2Fm.rakuten.co.jp%2Fbook%2Fi%2F20490363%2F&rafcid=wsc_i_is_c18bf7b5-1871-492a-a3f5-afa07ce3dd0a"}, {"label": "「DIE WITH ZERO 人生が豊かになりすぎる究極のルール」（ビル・パーキンス）", "label_en": "Die With Zero — Bill Perkins (Japanese edition)", "url": "https://hb.afl.rakuten.co.jp/hgc/g00q072n.kll75f32.g00q072n.kll76c1e/?pc=https%3A%2F%2Fitem.rakuten.co.jp%2Fbook%2F16433838%2F&m=http%3A%2F%2Fm.rakuten.co.jp%2Fbook%2Fi%2F20109362%2F&rafcid=wsc_i_is_c18bf7b5-1871-492a-a3f5-afa07ce3dd0a"}, {"label": "「ジェイソン流お金の増やし方 改訂版」（厚切りジェイソン）", "label_en": "Jason-ryu: How to Grow Your Money, revised ed. — Atsugiri Jason (Japanese)", "url": "https://hb.afl.rakuten.co.jp/hgc/g00q072n.kll75f32.g00q072n.kll76c1e/?pc=https%3A%2F%2Fitem.rakuten.co.jp%2Fbook%2F17970148%2F&m=http%3A%2F%2Fm.rakuten.co.jp%2Fbook%2Fi%2F21376226%2F&rafcid=wsc_i_is_c18bf7b5-1871-492a-a3f5-afa07ce3dd0a"}, {"label": "「きみのお金は誰のため ボスが教えてくれた「お金の謎」と「社会のしくみ」」（田内学）", "label_en": "Whose Money Is It Anyway? — Manabu Tauchi (Japanese)", "url": "https://hb.afl.rakuten.co.jp/hgc/g00q072n.kll75f32.g00q072n.kll76c1e/?pc=https%3A%2F%2Fitem.rakuten.co.jp%2Fbook%2F17607484%2F&m=http%3A%2F%2Fm.rakuten.co.jp%2Fbook%2Fi%2F21042739%2F&rafcid=wsc_i_is_c18bf7b5-1871-492a-a3f5-afa07ce3dd0a"}],
    tags_ja: ["お金の不安", "マネー本", "ランキング"],
